274	/// Hide hidden candidates when visible ones exist, deduplicate by id and sort
275	/// into the presentation order shared by every completion source.
276	fn finalize_completions(
277	    mut completions: Vec<CompletionCandidate>,
278	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
279	    if completions.iter().any(|a| !a.is_hide_set()) {
280	        completions.retain(|a| !a.is_hide_set());
281	    }
282	    let mut seen_ids = HashSet::new();
283	    completions.retain(move |a| {
284	        if let Some(id) = a.get_id().cloned() {
285	            seen_ids.insert(id)
286	        } else {
287	            true
288	        }
289	    });
290	
291	    let mut tags = Vec::new();
292	    for candidate in &completions {
293	        let tag = candidate.get_tag().cloned();
294	        if !tags.contains(&tag) {
295	            tags.push(tag);
296	        }
297	    }
298	    completions.sort_by_key(|c| {
299	        (
300	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
301	            c.get_display_order(),
302	        )
303	    });
304	
305	    Ok(completions)
306	}
