384	fn complete_option(
385	    arg: &clap_lex::ParsedArg<'_>,
386	    cmd: &clap::Command,
387	    current_dir: Option<&std::path::Path>,
388	    disabled: &HashSet<Id>,
389	) -> Vec<CompletionCandidate> {
390	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
391	    let mut completions = Vec::<CompletionCandidate>::new();
392	    if arg.is_empty() {
393	        completions.extend(longs_and_visible_aliases(cmd, disabled));
394	        completions.extend(hidden_longs_aliases(cmd, disabled));
395	
396	        let dash_or_arg = if arg.is_empty() {
397	            "-".into()
398	        } else {
399	            arg.to_value_os().to_string_lossy()
400	        };
401	        completions.extend(
402	            shorts_and_visible_aliases(cmd, disabled)
403	                .into_iter()
404	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
405	        );
406	    } else if arg.is_stdio() {
407	        // HACK: Assuming knowledge of is_stdio
408	        let dash_or_arg = if arg.is_empty() {
409	            "-".into()
410	        } else {
411	            arg.to_value_os().to_string_lossy()
412	        };
413	        completions.extend(
414	            shorts_and_visible_aliases(cmd, disabled)
415	                .into_iter()
416	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
417	        );
418	
419	        completions.extend(longs_and_visible_aliases(cmd, disabled));
420	        completions.extend(hidden_longs_aliases(cmd, disabled));
421	    } else if arg.is_escape() {
422	        // HACK: Assuming knowledge of is_escape
423	        completions.extend(longs_and_visible_aliases(cmd, disabled));
424	        completions.extend(hidden_longs_aliases(cmd, disabled));
425	    } else if let Some((flag, value)) = arg.to_long() {
426	        if let Ok(flag) = flag {
427	            if let Some(value) = value {
428	                let opt = cmd.get_arguments().find(|a| {
429	                    a.get_long_and_visible_aliases()
430	                        .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
431	                });
432	                if let Some(arg) = opt {
433	                    if !disabled.contains(arg.get_id()) {
434	                        completions.extend(
435	                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
436	                                .into_iter()
437	                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
438	                        );
439	                    }
440	                }
441	            } else {
442	                completions.extend(
443	                    longs_and_visible_aliases(cmd, disabled)
444	                        .into_iter()
445	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
446	                );
447	                completions.extend(
448	                    hidden_longs_aliases(cmd, disabled)
449	                        .into_iter()
450	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
451	                );
452	            }
453	        }
454	    } else if let Some(short) = arg.to_short() {
455	        if !short.is_negative_number() {
456	            // Find the first takes_values option.
457	            let (leading_flags, takes_value_opt, mut short, _) = parse_shortflags(cmd, short);
458	
459	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
460	            if let Some(opt) = takes_value_opt {
461	                if !disabled.contains(opt.get_id()) {
462	                    let mut peek_short = short.clone();
463	                    let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
464	                        short.next_flag();
465	                        true
466	                    } else {
467	                        false
468	                    };
469	
470	                    let value = short.next_value_os().unwrap_or(OsStr::new(""));
471	                    completions.extend(
472	                        complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
473	                            .into_iter()
474	                            .map(|comp| {
475	                                let sep = if has_equal { "=" } else { "" };
476	                                comp.add_prefix(format!("-{leading_flags}{sep}"))
477	                            }),
478	                    );
479	                }
480	            } else {
481	                completions.extend(
482	                    shorts_and_visible_aliases(cmd, disabled)
483	                        .into_iter()
484	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
485	                );
486	            }
487	        }
488	    }
489	    debug!("complete_option: completions={completions:?}");
490	    completions
491	}
