429	/// Create [`CompletionCandidate`]s for [`clap::builder::PossibleValue`]
430	///
431	/// This is implicitly applied for arguments with either a [`clap::builder::PossibleValuesParser`] or [`clap::builder::EnumValueParser`].
432	///
433	/// Using this explicitly is intended for arguments that also accept other value formats that need
434	/// to be completed and the completer is eager ([`ValueCandidates`]).
435	/// For lazy completion, see [`complete_possible_values`].
436	pub fn possible_value_candidates(
437	    values: impl IntoIterator<Item = clap::builder::PossibleValue>,
438	) -> Vec<CompletionCandidate> {
439	    values
440	        .into_iter()
441	        .map(|p| {
442	            CompletionCandidate::new(OsString::from(p.get_name()))
443	                .help(p.get_help().cloned())
444	                .hide(p.is_hide_set())
445	        })
446	        .collect()
447	}
448	
449	/// Create [`CompletionCandidate`]s for [`clap::builder::PossibleValue`]
450	///
451	/// This is implicitly applied for arguments with either a [`clap::builder::PossibleValuesParser`] or [`clap::builder::EnumValueParser`].
452	///
453	/// Using this explicitly is intended for arguments that also accept other value formats that need
454	/// to be completed and the completer is lazy ([`ValueCompleter`]).
455	/// For eager completion, see [`possible_value_candidates`].
456	pub fn complete_possible_values(
457	    value: &OsStr,
458	    values: impl IntoIterator<Item = clap::builder::PossibleValue>,
459	) -> Vec<CompletionCandidate> {
460	    let mut values = possible_value_candidates(values);
461	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
462	    values
463	}
