#![cfg(feature = "unstable-dynamic")]

use clap::{builder::PossibleValue, Command};

fn cmd() -> Command {
    Command::new("fmt")
        .arg(
            clap::Arg::new("format")
                .long("format")
                .num_args(1..=2)
                .value_parser([
                    PossibleValue::new("json"),
                    PossibleValue::new("yaml"),
                    PossibleValue::new("toml"),
                ])
                .value_delimiter(','),
        )
        .arg(
            clap::Arg::new("raw")
                .long("raw")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("format"),
        )
}

fn run(args: &[&str], idx: usize) -> String {
    let mut c = cmd();
    match clap_complete::engine::complete(
        &mut c,
        args.iter().map(|s| (*s).into()).collect(),
        idx,
        None,
    ) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| c.get_value().to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join("\n"),
        Err(e) => format!("ERR: {e}"),
    }
}

