        (&["fmt", "--format=json,yaml,", ""], 2, "trailing comma after 2"),
        (&["fmt", "--format=json,yaml,toml", ""], 2, "three segments"),
        (&["fmt", "--format=json,yaml,", "--raw"], 3, "raw after full"),
        (&["fmt", "--format=json", "--raw"], 2, "raw after one"),
        (&["fmt", "--format", "json,", ""], 2, "separate word json,"),
        (&["fmt", "--format", "json,yaml", ""], 3, "separate 2 vals"),
