use clap::{builder::PossibleValue, Command};

fn cmd() -> Command {
    Command::new("fmt")
        .arg(
            clap::Arg::new("format")
                .long("format")
                .num_args(1..=2)
                .value_parser([
                    PossibleValue::new("json"),
                    PossibleValue::new("yaml"),
                    PossibleValue::new("toml"),
                ])
                .value_delimiter(','),
        )
        .arg(
            clap::Arg::new("raw")
                .long("raw")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("format"),
        )
        .arg(clap::Arg::new("pos").value_parser(["p1","p2"]))
}

fn main() {
    let cases: &[&[&str]] = &[
        &["fmt", "--format=json", "yaml"],
        &["fmt", "--format=json", "p1"],
        &["fmt", "--format=json", "json"],
        &["fmt", "--format", "json", "yaml"],
        &["fmt", "--format=json,", "yaml"],
        &["fmt", "--format=json,", "p1"],
        &["fmt", "--format=json,yaml", "p1"],
        &["fmt", "--format=json", "--raw"],
        &["fmt", "--format=json,", "--raw"],
    ];
    for args in cases {
        let c = cmd();
        let r = c.try_get_matches_from(args.iter());
        match r {
            Ok(m) => println!("OK   {args:?} -> format={:?} raw={:?} pos={:?}",
                m.get_many::<String>("format").map(|v| v.cloned().collect::<Vec<_>>()),
                m.get_one::<bool>("raw"),
                m.get_many::<String>("pos").map(|v| v.cloned().collect::<Vec<_>>())),
            Err(e) => println!("ERR  {args:?} -> {}", e.to_string().lines().next().unwrap()),
        }
    }
}
