use clap::Command;
fn build(r: &str) -> Command {
    let a = clap::Arg::new("f").long("f").value_parser(["a","b","c"]).value_delimiter(',');
    let a = match r {
        "1" => a.num_args(1), "0..=2" => a.num_args(0..=2), "1..=2" => a.num_args(1..=2),
        "2" => a.num_args(2), "2..=3" => a.num_args(2..=3), "1.." => a.num_args(1..),
        _ => a,
    };
    Command::new("c").arg(a)
}
fn main() {
    for r in ["1","0..=2","1..=2","2","2..=3","1.."] {
        for n in 1..=4usize {
            let v = vec!["a"; n].join(",");
            let args = vec!["c".to_string(), format!("--f={v}")];
            let res = match build(r).try_get_matches_from(args.iter()) {
                Ok(_) => "OK".to_string(),
                Err(e) => {
                    let s = e.to_string();
                    let l = s.lines().next().unwrap();
                    if l.contains("valid") {"INVALID".to_string()}
                    else if l.contains("too many") {"TOOMANY".to_string()}
                    else {"ERR".to_string()}
                }
            };
            print!("{r:7} seg={n}: {res:8} ");
        }
        println!();
    }
}
