fn cursor_delimited<'s>(opt: &clap::Arg, value: &'s OsStr) -> Result<Option<DelimCursor<'s>>, ()> {
    let Some(delim) = is_bounded_delimited(opt) else {
        return Ok(None);
    };
    let max = opt.get_num_args().expect("built").max_values();
    let value_str = value.to_str().ok_or(())?;
    let delim_str = delim.encode_utf8(&mut [0; 4]);

    let Some(pos) = value_str.rfind(delim) else {
        return Ok(Some(DelimCursor {
            current: value,
            closed: Vec::new(),
            prefix: "",
        }));
    };
    let (prefix, current) = value_str.split_at(pos + delim.len_utf8());
    let closed: Vec<&str> = prefix[..prefix.len() - delim_str.len()].split(delim).collect();
    if closed.iter().any(|s| s.is_empty()) || closed.len() >= max {
        return Err(());
    }
    Ok(Some(DelimCursor {
        current: OsStr::new(current),
        closed: closed.into_iter().map(OsStr::new).collect(),
        prefix,
    }))
}

