#![cfg(feature = "unstable-dynamic")]

use clap::{builder::PossibleValue, Command};

fn cmd() -> Command {
    Command::new("fmt")
        .arg(
            clap::Arg::new("format")
                .long("format")
                .num_args(1..=2)
                .value_parser([
                    PossibleValue::new("json"),
                    PossibleValue::new("yaml"),
                    PossibleValue::new("toml"),
                ])
                .value_delimiter(','),
        )
        .arg(
            clap::Arg::new("raw")
                .long("raw")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("format"),
        )
}

fn run(args: &[&str], idx: usize) -> String {
    let mut c = cmd();
    match clap_complete::engine::complete(
        &mut c,
        args.iter().map(|s| (*s).into()).collect(),
        idx,
        None,
    ) {
        Ok(cs) => format!("OK: {}", cs
            .into_iter()
            .map(|c| c.get_value().to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join(" | ")),
        Err(e) => format!("ERR: {e}"),
    }
}

#[test]
fn scratch4() {
    let cases: &[(&[&str], usize, &str)] = &[
        (&["fmt", "--format", "json", ""], 2, "first value word cursor empty"),
        (&["fmt", "--format", "json,"], 2, "cursor on json, after --format"),
        (&["fmt", "--format", "json,yaml", ""], 3, "two values then empty"),
        (&["fmt", "--format", "json,", ""], 3, "dangling comma then empty"),
        (&["fmt", "--format", "json,yaml,"], 2, "cursor on json,yaml,"),
