        (&["fmt", "-f", "json,", ""], 3, "short dangling then empty"),
        (&["fmt", "-f=json,"], 1, "short equals cursor dangling"),
    ];
    for (args, idx, desc) in cases {
        println!("=== {desc} (idx={idx})\n{}", run(args, *idx));
    }
}

