        return Err(());
    }
    let closed = used.len() + segments.len();
    if closed > max || (closed == max && dangling) {
        return Err(());
    }
    used.extend(segments.iter().map(|s| s.to_os_string()));

    // Only a dangling delimiter lets an attached word continue; a space
    // separated word keeps accepting values until the range is full.
