    current: &'s OsStr,
    /// Closed segments that precede it, in order.
    closed: Vec<&'s OsStr>,
    /// Everything in this shell word before the current segment, including the
    /// trailing delimiter, to re-prefix candidates with.
    prefix: &'s str,
